'use strict';
let worryWords='',worryPath='',worryStep='',worrySource='',skillDraft={facts:'',interpretation:'',unknown:'',balanced:''},checkStage=0,skillThoughtId='',distanceWords='',distanceShown=false,distanceValue='',distanceKindness='',actionCategory='connection',actionEnergy='gentle';
let skillEdits={worry:null,check:null,distance:null},skillSourceWords='',skillSaving=false,bodyDay=AntarSkills.dayKey(new Date()),bodyHours='',bodyQuality='unknown',bodyEnergy='unknown',bodyWords='',bodyVersion=null,bodySaving=false;
const skillTitles={worry:'Problem, ya “what if”?',check:'A gentler thought check',distance:'Thought se thoda faasla'};
function skillsArt(type='paths'){const drawings={paths:'<path d="M28 101h42q22 0 22-22V37m0 42q0 22 22 22h42"/><circle cx="92" cy="31" r="6"/><circle cx="23" cy="101" r="6"/><circle cx="162" cy="101" r="6"/>',check:'<rect x="22" y="27" width="50" height="70" rx="9"/><rect x="79" y="43" width="50" height="70" rx="9"/><path d="m88 67 10 10 19-23M32 43h29M32 55h24M32 68h17"/>',distance:'<circle cx="53" cy="72" r="27"/><path d="M89 72h31m-9-10 12 10-12 10"/><circle cx="150" cy="72" r="14"/><path d="M27 110q62 18 143-4"/>',actions:'<path d="M37 111q25-43 61-42t55-38M45 111l-8-1-2-10M143 29l13-2-2 14"/><circle cx="50" cy="81" r="5"/><circle cx="94" cy="69" r="5"/><circle cx="142" cy="45" r="5"/>',brain:'<path d="M37 86q-13-20 2-32-2-23 22-23 8-20 25-4 20-18 32 2 29-3 28 23 19 14 5 33-1 22-29 19-16 14-33 0-22 13-35-3-23 7-17-15Z"/><path d="M88 29v74M57 45q19 0 18 19M47 76q17-9 29 8m30-40q-3 17 17 20m-22 21q15 12 29-3"/>'};return `<svg class="skills-art" viewBox="0 0 190 140" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[type]||drawings.paths}</svg>`}
function evidenceNote(key){const source=AntarSkills.sources[key]||AntarSkills.sources.distance;return `<details class="evidence-note"><summary>Source &amp; limits · clinical review pending</summary><p>Antar’s original, shortened self-help adaptation draws on <a href="${source.url}" target="_blank" rel="noopener noreferrer">${esc(source.title)}</a>. Source checked 13 November 2026.</p><p>Clinical review: <strong>not yet reviewed by a qualified psychologist</strong>. The supporting approach does not establish that Antar is effective treatment. This is not a diagnosis or a replacement for professional care.</p><p>If this feels uncomfortable or turns into more checking, stop. You can <a href="#comfort">choose something familiar</a>, <a href="#reset">notice your surroundings</a>, or <a href="#help">find human support</a>.</p></details>`}
function skillHead(title,subtitle,type){return `<a class="install-link" href="#skills">‹ Skills, at your pace</a><div class="skill-heading"><div>${skillsArt(type)}</div><h1>${title}</h1><p class="sub">${subtitle}</p></div>`}
function skillPrivacy(){return '<a class="install-link" href="#skills">Leave without saving</a><p class="note">Writing is optional. Drafts stay in this open page until you save. Saved exercises are local to this browser, without app encryption or sync. Nothing is sent to AI.</p>'}
function skillsHub(){const cards=[['worry','paths','Problem, ya “what if”?','Choose one useful next step.','Understand the loop'],['check','check','A gentler thought check','Facts, meaning, and what is still unknown.','Separate the pieces'],['distance','distance','Thought se thoda faasla','Notice a thought, without settling it.','Make a little room'],['actions','actions','Small actions, with meaning','Connection, enjoyment, or what matters to you.','Find a manageable action']];return `<p class="greeting">Skills, at your pace</p><h1>A little clarity.<br>A little practice.</h1><p class="sub">Psychology-informed tools. A few minutes, if useful. No score and nothing to complete.</p><div class="skill-grid">${cards.map(([id,art,title,copy,cta])=>`<a class="skill-door skill-${id}" href="#skill/${id}">${skillsArt(art)}<h2>${title}</h2><p>${copy}</p><span>${cta}</span></a>`).join('')}</div><a class="brain-door" href="#brain">${skillsArt('brain')}<span><h2>A practical brain corner</h2><p>Sleep, stress, attention, learning. Useful explanations with clear limits.</p></span></a><div class="section-head"><h2>What you chose to keep</h2></div>${savedSkillCards()}<div class="review-note"><h3>Evidence, without a promise.</h3><p>These are original adaptations of public self-help guidance. Every exercise links its source. Clinical review is outstanding; Antar itself has not been validated as treatment.</p></div>${personalBackupControls()}`}
function savedSkillCards(){const saved=personalItems.filter(x=>x.kind==='skill-note').sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));return saved.map(x=>`<article class="saved-skill"><span class="small">${new Date(x.createdAt).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span><a href="#skill-note/${encodeURIComponent(x.id)}">${esc(x.title)}</a><button class="text-btn" data-personal-remove="${esc(x.id)}">Remove</button></article>`).join('')||'<p class="empty">You can use every skill without saving an exercise.</p>'}
function worryTool(){const path=AntarSkills.paths[worryPath];return `${skillHead('Problem hai,<br>ya “what if” loop?','Let’s separate one thing you can work with from a question you cannot settle right now.','paths')}<label class="field" for="worry-words">What keeps coming back? <span class="small">(optional)</span></label><textarea id="worry-words" maxlength="1200" placeholder="Wahi sawal, baar-baar…">${esc(worryWords)}</textarea><h2 class="skill-prompt">Which feels closest?</h2><div class="worry-paths">${Object.entries(AntarSkills.paths).map(([id,p])=>`<button class="worry-path ${worryPath===id?'selected':''}" data-worry-path="${id}" aria-pressed="${worryPath===id}"><strong>${p.title}</strong><span>${p.hi}</span></button>`).join('')}</div>${path?`<section class="next-piece"><p class="small">Chosen by you</p><h2>${path.next}</h2><p>${path.hint}</p><label class="field" for="worry-step">${path.prompt} <span class="small">(optional)</span></label><textarea id="worry-step" maxlength="700">${esc(worryStep)}</textarea>${worryPath==='information'?`<label class="field" for="worry-source">Who or what could help—and when would you stop checking?</label><input id="worry-source" maxlength="300" value="${esc(worrySource)}" placeholder="One useful source, one stopping point">`:''}${['action','information'].includes(worryPath)?'<button class="secondary" data-skill="worry-experiment">Use my step in an experiment</button>':'<a class="install-link" href="#skill/distance">Try a little distance from the thought</a>'}<button class="primary" data-save-skill="worry" ${skillSaving||!personalReady?'disabled':''}>${skillSaving?'Saving…':'Save this exercise'}</button></section>`:''}${skillPrivacy()}${evidenceNote('worry')}`}
const checkPrompts=[['facts','What happened?','Jo directly dekha ya suna. The situation, in plain words.','For example: my message has not had a reply.'],['interpretation','What meaning did my mind add?','An interpretation can be possible without being established. Real harm and unfairness also deserve care.','For example: perhaps they are upset with me.'],['unknown','What remains unknown?','Abhi kya pata nahi? You do not have to resolve this uncertainty.','For example: I do not know why they have not replied.']];
function thoughtCheck(){const [key,title,copy,placeholder]=checkPrompts[checkStage];return `${skillHead('A gentler<br>thought check.','Separate what happened, what it meant to you, and what remains open. A fairer view can still acknowledge a real problem.','check')}${skillSourceWords?`<div class="brought-words"><span class="small">Words you chose to bring in</span><p>${esc(skillSourceWords)}</p><p class="small">These are not automatically treated as facts or interpretations. You choose where each piece belongs.</p></div>`:''}<div class="check-path" aria-label="Thought check steps">${checkPrompts.map((p,i)=>`<button data-check-stage="${i}" class="${checkStage===i?'active':''}" aria-pressed="${checkStage===i}"><span>${i+1}</span>${['Happened','Meaning','Unknown'][i]}</button>`).join('')}</div><section class="check-paper"><p class="small">${checkStage+1} of 3 · any field can stay blank</p><h2>${title}</h2><p>${copy}</p><label class="visually-hidden" for="check-words">${title}</label><textarea id="check-words" maxlength="1400" data-check-key="${key}" placeholder="${placeholder}">${esc(skillDraft[key])}</textarea><div class="check-controls">${checkStage>0?'<button class="text-btn" data-skill="check-back">Previous piece</button>':''}${checkStage<2?'<button class="secondary" data-skill="check-next">Next piece · or skip</button>':''}</div></section>${checkStage===2?`<label class="field" for="check-balanced">A fairer possibility, if one fits <span class="small">(optional)</span></label><textarea id="check-balanced" maxlength="1400" placeholder="Something realistic or neutral. It need not feel positive.">${esc(skillDraft.balanced)}</textarea><div class="check-summary">${checkPrompts.map(([k,label])=>`<div><span>${label}</span><p>${esc(skillDraft[k]||'Left open by you.')}</p></div>`).join('')}</div><button class="primary" data-save-skill="check" ${skillSaving||!personalReady?'disabled':''}>${skillSaving?'Saving…':'Save my thought check'}</button>`:''}<p class="small">A shortened CBT-inspired reflection—not a full CBT session or an evaluation of whether you are “thinking correctly.”</p>${skillPrivacy()}${evidenceNote('check')}`}
function thoughtDistance(){return `${skillHead('Thought se<br>thoda faasla.','Notice what your mind is saying. You don’t need to argue with it or make it disappear.','distance')}<label class="field" for="distance-words">A thought, in your own words <span class="small">(optional)</span></label><textarea id="distance-words" maxlength="900" placeholder="For example: I’m not good enough.">${esc(distanceWords)}</textarea><button class="secondary" data-skill="distance-phrase">Try a little space around these words</button>${distanceShown?`<blockquote class="distance-quote">${esc(AntarSkills.distance(distanceWords)||'I notice a thought is here. I do not need to finish it right now.')}</blockquote><p class="small">An invitation to notice a thought, not a statement that your concern is false.</p>`:''}<div class="outside-option"><h2>Stay with the room, if you prefer.</h2><p>Look at a familiar object or notice the chair beneath you. No need to close your eyes or focus inward.</p><a class="install-link" href="#reset">Choose an optional grounding exercise</a></div><details ${distanceValue||distanceKindness?'open':''}><summary>A value, or a kinder response? Optional.</summary><p class="sub">What would you like to stand for in this moment?</p><div class="chips">${['Care','Honesty','Connection','Self-respect','Curiosity','Rest'].map(value=>`<button class="chip ${distanceValue===value?'selected':''}" data-distance-value="${value}" aria-pressed="${distanceValue===value}">${value}</button>`).join('')}</div><label class="field" for="distance-kindness">A gentler sentence in your own voice</label><textarea id="distance-kindness" maxlength="700" placeholder="What might you say to someone you care about?">${esc(distanceKindness)}</textarea><a class="install-link" href="#skill/actions">Choose a small action that matters</a></details><button class="primary" data-save-skill="distance" ${skillSaving||!personalReady?'disabled':''}>${skillSaving?'Saving…':'Save this reflection'}</button>${skillPrivacy()}${evidenceNote('distance')}`}
function meaningfulActions(){const labels={connection:'Connection',enjoyment:'Enjoyment',meaning:'Something important to me'};return `${skillHead('Small actions.<br>Your kind of meaning.','A way to explore what supports you. Match the size of the action to the energy you have.','actions')}<h2 class="skill-prompt">What would you like room for?</h2><div class="chips">${Object.entries(labels).map(([id,label])=>`<button class="chip ${actionCategory===id?'selected':''}" data-action-category="${id}" aria-pressed="${actionCategory===id}">${label}</button>`).join('')}</div><h2 class="skill-prompt">How much feels manageable?</h2><div class="energy-pills">${[['gentle','Very little energy'],['some','A little room'],['more','More room today']].map(([id,label])=>`<button class="chip ${actionEnergy===id?'selected':''}" data-action-energy="${id}" aria-pressed="${actionEnergy===id}">${label}</button>`).join('')}</div><p class="small">More is not better. These are your choices, not an energy assessment.</p><div class="action-suggestions">${AntarSkills.suggestions(actionCategory,actionEnergy).map(text=>`<button data-action-seed="${esc(text)}"><span class="action-dot"></span><span>${esc(text)}<small>Make this my own experiment</small></span><span>›</span></button>`).join('')}</div><a class="install-link" href="#experiments">I have my own idea</a><p class="note">Nothing is saved by choosing a suggestion. You can edit it in Experiments and save only if you want. There are no targets or reminders.</p>${evidenceNote('actions')}`}
function skillView(id){return({worry:worryTool,check:thoughtCheck,distance:thoughtDistance,actions:meaningfulActions}[id]||notFound)()}
function savedSkillView(id){const item=personalItems.find(x=>x.id===id&&x.kind==='skill-note');if(!item)return `<a class="install-link" href="#skills">‹ Skills</a><h1>${personalReady?'This exercise is not here.':'Opening your saved exercise…'}</h1>`;const fields=item.fields||{};return `<a class="install-link" href="#skills">‹ Skills</a><p class="greeting">Saved by you · ${new Date(item.createdAt).toLocaleDateString('en-IN')}</p><h1>${esc(item.title)}</h1>${Object.entries(fields).filter(([,v])=>v).map(([label,value])=>`<section class="saved-piece"><h2>${esc(label)}</h2><p>${esc(value)}</p></section>`).join('')}<button class="secondary" data-edit-skill="${esc(id)}">Open &amp; edit</button><button class="text-btn" data-personal-remove="${esc(id)}">Remove</button>${evidenceNote(item.skill)}${personalBackupControls()}`}
function skillPayload(type){if(type==='worry')return{path:worryPath,words:worryWords,step:worryStep,source:worryPath==='information'?worrySource:'',fields:{'What keeps coming back':worryWords,'My chosen path':AntarSkills.paths[worryPath]?.title||'','My next piece':worryStep,'Information and stopping point':worryPath==='information'?worrySource:''}};if(type==='check')return{...skillDraft,thoughtId:skillThoughtId,sourceWords:skillSourceWords,fields:{'Words I brought in':skillSourceWords,'What happened':skillDraft.facts,'My interpretation':skillDraft.interpretation,'What remains unknown':skillDraft.unknown,'A fairer possibility':skillDraft.balanced}};return{words:distanceWords,value:distanceValue,kindness:distanceKindness,fields:{'The thought I noticed':distanceWords,'A little distance':AntarSkills.distance(distanceWords),'A value I chose':distanceValue,'A kinder response':distanceKindness}}}
async function saveSkill(type){if(skillSaving||!personalReady||!['worry','check','distance'].includes(type))return;const payload=skillPayload(type);if(type==='worry'&&!worryPath)return toast('Choose what feels closest, or leave this exercise unsaved.');if(type==='check'&&!Object.values(skillDraft).some(x=>x.trim()))return toast('Add a few words to keep, or leave it unsaved.');if(type==='distance'&&!distanceWords.trim()&&!distanceKindness.trim()&&!distanceValue)return toast('Add something you want to keep, or leave it unsaved.');skillSaving=true;try{const now=new Date().toISOString(),editing=skillEdits[type];const item={id:editing?.id||personalId(),kind:'skill-note',title:skillTitles[type],skill:type,payload,fields:payload.fields,createdAt:editing?.createdAt||now,updatedAt:now};await writePersonal(item,editing?.updatedAt??null);skillEdits[type]=null;await refreshPersonal(true);go('skill-note/'+encodeURIComponent(item.id));toast('Saved on this device.')}catch(error){toast(error.message||'Could not save. Your draft is still here.')}finally{skillSaving=false;if(route.startsWith('skill/'))render(true)}}
function loadSkill(item){const p=item.payload||{};skillEdits[item.skill]={...item};if(item.skill==='worry'){worryPath=p.path||'';worryWords=p.words||'';worryStep=p.step||'';worrySource=p.source||''}if(item.skill==='check'){skillDraft={facts:p.facts||'',interpretation:p.interpretation||'',unknown:p.unknown||'',balanced:p.balanced||''};skillThoughtId=p.thoughtId||'';skillSourceWords=p.sourceWords||'';checkStage=0}if(item.skill==='distance'){distanceWords=p.words||'';distanceValue=p.value||'';distanceKindness=p.kindness||'';distanceShown=true}go('skill/'+item.skill)}
const brainLessons=[
 {id:'sleep',title:'Sleep is part of the picture.',topic:'Sleep',art:'moon',body:'Sleep quantity and quality both matter. Adequate sleep supports emotional wellbeing, attention and memory; it is not the only influence on how you feel.',try:'If it suits your circumstances, choose a more consistent waking time to explore.',limit:'One difficult night does not explain a mood or diagnose a sleep disorder. Persistent sleep difficulties deserve a healthcare conversation.',source:'sleep'},
 {id:'attention',title:'A scattered moment is not a verdict.',topic:'Attention',art:'focus',body:'Stress can make concentration more difficult. A moment of distraction does not tell us which brain system is active or whether you have a condition.',try:'Choose one manageable task. Give it a small, comfortable amount of attention, with distractions reduced if possible.',limit:'Antar does not test attention or diagnose ADHD. If concentration problems are persistent or disruptive, consider professional support.',source:'stress'},
 {id:'stress',title:'Mind and body share a moment.',topic:'Stress',art:'waves',body:'Stress can come with changes in sleep, concentration, mood and physical comfort. People respond differently. These experiences have many possible causes.',try:'Choose a familiar comfort, look around the room, or ask someone safe for company.',limit:'A body feeling cannot tell Antar your cortisol, vagal tone, or nervous-system state. New or concerning physical symptoms need appropriate medical care.',source:'stress'},
 {id:'learning',title:'Learning also needs rest.',topic:'Learning',art:'thread',body:'Insufficient sleep can interfere with learning, memory and performance. Neuroscience findings describe general processes; they do not measure what is happening in your brain through this app.',try:'Keep one useful idea somewhere you can find it. Revisit when you have room, rather than trying to absorb everything now.',limit:'There is no brain-rewiring score, dopamine measurement, or guaranteed timeline here.',source:'learning'}
];
function brainIllustration(type){const shapes={moon:'<path d="M77 22a39 39 0 1 0 38 55A39 39 0 0 1 77 22Z"/><path d="M121 27v12m-6-6h12M139 56v8m-4-4h8"/>',focus:'<circle cx="85" cy="65" r="33"/><circle cx="85" cy="65" r="12"/><path d="M85 18v10m0 74v10M38 65h10m74 0h10"/>',waves:'<path d="M30 44q25-25 50 0t50 0M30 67q25-25 50 0t50 0M30 90q25-25 50 0t50 0"/>',thread:'<path d="M29 92q25-73 50-20t53-40"/><circle cx="29" cy="92" r="6"/><circle cx="132" cy="32" r="6"/><path d="M49 103h78"/>'};return `<svg viewBox="0 0 170 130" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true">${shapes[type]}</svg>`}
function brainCorner(){return `<a class="install-link" href="#skills">‹ Skills</a><p class="greeting">A practical neuroscience corner</p><h1>Understand a little.<br>Leave room for more.</h1><p class="sub">Short explanations, useful possibilities, and honest limits. No brain scores.</p><a class="install-link" href="#body-notes">Sleep &amp; energy notes · optional</a><div class="brain-lessons">${brainLessons.map(card=>`<article class="brain-lesson"><div class="brain-visual">${brainIllustration(card.art)}<span>${card.topic}</span></div><h2>${card.title}</h2><p>${card.body}</p><div class="brain-try"><strong>Something to explore</strong><p>${card.try}</p></div><details><summary>Source &amp; limits</summary><p>${card.limit}</p><a class="install-link" href="${AntarSkills.sources[card.source].url}" target="_blank" rel="noopener noreferrer">${AntarSkills.sources[card.source].title}</a><p class="small">Source checked 13 November 2026. Original educational summary; not personalised medical advice. Clinical review outstanding.</p></details></article>`).join('')}</div><a class="primary skill-block-link" href="#body-notes">Optional sleep &amp; energy notes</a><p class="note">Sleep and energy notes stay separate from your downtime history. You choose whether to record anything.</p>`}
function loadBodyDay(day){bodyDay=day;const item=personalItems.find(x=>x.kind==='body-note'&&x.id==='body-note:'+day);bodyHours=item?.hours===null||item?.hours===undefined?'':String(item.hours);bodyQuality=item?.sleepQuality||'unknown';bodyEnergy=item?.energy||'unknown';bodyWords=item?.text||'';bodyVersion=item?{...item}:null;render(true)}
function bodyHasChanges(){return bodyHours!==(bodyVersion?.hours===null||bodyVersion?.hours===undefined?'':String(bodyVersion.hours))||bodyQuality!==(bodyVersion?.sleepQuality||'unknown')||bodyEnergy!==(bodyVersion?.energy||'unknown')||bodyWords!==(bodyVersion?.text||'')}
function bodyNotes(){if(personalReady&&!bodyVersion&&!bodyHasChanges()){const existing=personalItems.find(x=>x.id==='body-note:'+bodyDay);if(existing){bodyVersion={...existing};bodyHours=existing.hours===null?'':String(existing.hours);bodyQuality=existing.sleepQuality;bodyEnergy=existing.energy;bodyWords=existing.text||''}}const summary=AntarSkills.bodySummary(personalItems);return `<a class="install-link" href="#brain">‹ Brain corner</a><h1>Sleep &amp; energy.<br>A note, if useful.</h1><p class="sub">One optional note per day. Missing days stay unknown. This does not measure your brain or infer causes.</p><label class="field" for="body-day">Day</label><input id="body-day" type="date" value="${esc(bodyDay)}" max="${AntarSkills.dayKey(new Date())}"><label class="field" for="body-quality">How did your sleep feel?</label><select id="body-quality" class="section-select">${[['unknown','Not sure / leave blank'],['poor','Not restful'],['mixed','Mixed'],['rested','Restful']].map(([id,label])=>`<option value="${id}" ${bodyQuality===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="body-hours">Estimated hours <span class="small">(optional)</span></label><input id="body-hours" type="number" inputmode="decimal" min="0" max="24" step="0.5" value="${esc(bodyHours)}" placeholder="Leave blank if unknown"><label class="field" for="body-energy">How was your energy?</label><select id="body-energy" class="section-select">${[['unknown','Not sure / leave blank'],['low','Low'],['steady','Steady'],['high','High']].map(([id,label])=>`<option value="${id}" ${bodyEnergy===id?'selected':''}>${label}</option>`).join('')}</select><label class="field" for="body-words">Anything worth remembering? <span class="small">(optional)</span></label><input id="body-words" maxlength="200" value="${esc(bodyWords)}"><button class="primary" data-skill="save-body" ${bodySaving||!personalReady?'disabled':''}>${bodySaving?'Saving…':bodyVersion?'Save changes to this day':'Save this day’s note'}</button>${bodyVersion?'<p class="small">Editing your existing note for this day.</p>':''}${skillPrivacy()}<section class="body-observation"><h2>What you actually recorded</h2><p>${summary.days} saved ${summary.days===1?'day':'days'} in the last 30 days. ${summary.paired} with both sleep quality and energy selected.</p>${summary.ready?`<p>On ${summary.poorAndLow} of those ${summary.paired} days, you recorded both “not restful” sleep and low energy.</p><p class="small">A co-occurrence in saved notes—not evidence that one caused the other. Unrecorded days tell us nothing.</p>`:'<p class="small">No association summary yet. It needs at least 7 paired days spanning 14 days; you do not need to log toward that threshold.</p>'}</section><div class="body-history">${summary.entries.slice().reverse().map(item=>`<article><strong>${esc(item.day)}</strong><p>${{unknown:'Sleep left open',poor:'Not restful',mixed:'Mixed sleep',rested:'Restful'}[item.sleepQuality]||'Sleep left open'} · ${{unknown:'Energy left open',low:'Low energy',steady:'Steady energy',high:'High energy'}[item.energy]||'Energy left open'}${item.hours!==null&&item.hours!==undefined?' · ~'+esc(item.hours)+'h':''}</p>${item.text?`<p>${esc(item.text)}</p>`:''}<button class="text-btn" data-body-open="${item.day}">Open this day</button><button class="text-btn" data-personal-remove="${esc(item.id)}">Remove</button></article>`).join('')}</div>${personalBackupControls()}`}
async function saveBody(){if(bodySaving||!personalReady)return;if(!AntarSkills.validDay(bodyDay)||bodyDay>AntarSkills.dayKey(new Date()))return toast('Choose today or an earlier valid date.');const hours=bodyHours.trim()===''?null:Number(bodyHours);if(hours!==null&&(!Number.isFinite(hours)||hours<0||hours>24))return toast('Use an estimate between 0 and 24 hours, or leave it blank.');if(bodyQuality==='unknown'&&bodyEnergy==='unknown'&&hours===null&&!bodyWords.trim())return toast('Choose something to record, or leave the day unknown.');bodySaving=true;try{const now=new Date().toISOString();await writePersonal({id:'body-note:'+bodyDay,kind:'body-note',title:'Sleep & energy · '+bodyDay,day:bodyDay,hours,sleepQuality:bodyQuality,energy:bodyEnergy,text:bodyWords.trim(),createdAt:bodyVersion?.createdAt||now,updatedAt:now},bodyVersion?.updatedAt??null);await refreshPersonal(true);bodyVersion=personalItems.find(x=>x.id==='body-note:'+bodyDay);toast('Saved. No downtime log was created.')}catch(error){toast(error.message||'Could not save. Your note is still here.')}finally{bodySaving=false;render(true)}}
document.addEventListener('input',event=>{const e=event.target;if(e.id==='worry-words')worryWords=e.value;if(e.id==='worry-step')worryStep=e.value;if(e.id==='worry-source')worrySource=e.value;if(e.id==='check-words')skillDraft[e.dataset.checkKey]=e.value;if(e.id==='check-balanced')skillDraft.balanced=e.value;if(e.id==='distance-words'){distanceWords=e.value;distanceShown=false}if(e.id==='distance-kindness')distanceKindness=e.value;if(e.id==='body-hours')bodyHours=e.value;if(e.id==='body-words')bodyWords=e.value});
document.addEventListener('change',event=>{const e=event.target;if(e.id==='body-quality')bodyQuality=e.value;if(e.id==='body-energy')bodyEnergy=e.value;if(e.id==='body-day'){const next=e.value;if(bodyHasChanges()&&!confirm('Change day? Unsaved sleep and energy notes will be replaced.')){e.value=bodyDay;return}loadBodyDay(next)}});
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;if(el.dataset.worryPath){worryPath=el.dataset.worryPath;render(true);document.querySelector('.next-piece')?.scrollIntoView({block:'start'});return}if(el.dataset.checkStage!==undefined){checkStage=Number(el.dataset.checkStage);render(true);return}if(el.dataset.distanceValue){distanceValue=distanceValue===el.dataset.distanceValue?'':el.dataset.distanceValue;render(true);return}if(el.dataset.actionCategory){actionCategory=el.dataset.actionCategory;render(true);return}if(el.dataset.actionEnergy){actionEnergy=el.dataset.actionEnergy;render(true);return}if(el.dataset.actionSeed){experimentTitle=el.dataset.actionSeed;experimentPlan='I chose '+actionCategory+' with '+actionEnergy+' energy. I can change or skip this.';experimentMeaning=actionCategory;experimentEnergy=actionEnergy;experimentEditing='';go('experiments');return}if(el.dataset.thoughtCheck){const item=personalItems.find(x=>x.id===el.dataset.thoughtCheck&&x.kind==='thought');if(!item)return;if(Object.values(skillDraft).some(x=>x.trim())&&!confirm('Start a thought check from this saved thought? Your unsaved thought-check draft will be replaced.'))return;skillDraft={facts:'',interpretation:'',unknown:'',balanced:''};skillSourceWords=item.text.slice(0,1400);skillThoughtId=item.id;skillEdits.check=null;checkStage=0;go('skill/check');return}if(el.dataset.editSkill){const item=personalItems.find(x=>x.id===el.dataset.editSkill&&x.kind==='skill-note');if(item){const draft=skillPayload(item.skill).fields;if(Object.values(draft).some(x=>x.trim())&&!confirm('Open this saved exercise? The unsaved draft for this tool will be replaced.'))return;loadSkill(item)}return}if(el.dataset.saveSkill){await saveSkill(el.dataset.saveSkill);return}if(el.dataset.bodyOpen){if(bodyHasChanges()&&!confirm('Open this day? Unsaved sleep and energy notes will be replaced.'))return;loadBodyDay(el.dataset.bodyOpen);return}switch(el.dataset.skill){case'check-next':checkStage=Math.min(2,checkStage+1);render();break;case'check-back':checkStage=Math.max(0,checkStage-1);render();break;case'distance-phrase':distanceShown=true;render(true);break;case'worry-experiment':if(!worryStep.trim())return toast('Write a step first, or leave this exercise without saving.');experimentTitle=worryStep.trim().slice(0,160);experimentPlan=worrySource;experimentMeaning='';experimentEnergy='';experimentEditing='';go('experiments');break;case'save-body':await saveBody();break;}});

function clearSkillsDrafts(){worryWords='';worryPath='';worryStep='';worrySource='';skillDraft={facts:'',interpretation:'',unknown:'',balanced:''};skillSourceWords='';skillThoughtId='';skillEdits={worry:null,check:null,distance:null};checkStage=0;distanceWords='';distanceShown=false;distanceValue='';distanceKindness='';bodyDay=AntarSkills.dayKey(new Date());bodyHours='';bodyQuality='unknown';bodyEnergy='unknown';bodyWords='';bodyVersion=null;}

function onPersonalItemRemoved(item){if(item.kind==='body-note'&&bodyVersion?.id===item.id){const keepDraft=bodyHasChanges();bodyVersion=null;if(!keepDraft){bodyHours='';bodyQuality='unknown';bodyEnergy='unknown';bodyWords=''}}if(item.kind==='skill-note'&&skillEdits[item.skill]?.id===item.id)skillEdits[item.skill]=null;}
